import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherQuestionBank({ userName, teachingSubject }) {
  const [bankQuestions, setBankQuestions] = useState([]);
  
  // --- Form Input States ---
  const [questionText, setQuestionText] = useState('');
  const [questionCategory, setQuestionCategory] = useState('EXAM'); // EXAM or ACTIVITY
  const [questionType, setQuestionType] = useState('MCQ'); // MCQ or SHORT_ANSWER
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctAnswer, setCorrectAnswer] = useState('');
  const [targetGrade, setTargetGrade] = useState('Grade 8');

  // --- UI Filter State ---
  const [filterCategory, setFilterCategory] = useState('ALL'); // ALL, EXAM, ACTIVITY
  const [filterGrade, setFilterGrade] = useState('Grade 8');

  const currentSubject = teachingSubject || 'Mathematics';

  // Fetch all questions from the database bank
  const fetchBankQuestions = () => {
    axios.get('http://localhost:8082/api/question-bank')
      .then(res => {
        const data = Array.isArray(res.data) ? res.data : [];
        // Filter questions by this teacher's specific subject stream
        const filtered = data.filter(q => 
          String(q.subject || q.subject_name || '').toLowerCase().includes(currentSubject.toLowerCase())
        );
        setBankQuestions(filtered);
      })
      .catch(err => console.error("Error fetching repository data:", err));
  };

  useEffect(() => {
    fetchBankQuestions();
  }, [filterGrade]);

  // Insert question into database with automatic structural tagging
  const handleAddQuestion = (e) => {
    e.preventDefault();

    // Smart Tagging: Prefixes the question text to separate Exam vs Activity without database structural changes
    const taggedQuestionText = `[${questionCategory}] ${questionText}`;

    const payload = {
      question_text: taggedQuestionText,
      grade: targetGrade,
      subject: currentSubject,
      teacher_name: userName || 'Teacher',
      option_a: questionType === 'MCQ' ? optA : null,
      option_b: questionType === 'MCQ' ? optB : null,
      option_c: questionType === 'MCQ' ? optC : null,
      option_d: questionType === 'MCQ' ? optD : null,
      correct_answer: correctAnswer.trim().toUpperCase()
    };

    axios.post('http://localhost:8082/api/question-bank', payload)
      .then(() => {
        alert("Success: Master question committed to the centralized bank!");
        setQuestionText('');
        setCorrectAnswer('');
        setOptA(''); setOptB(''); setOptC(''); setOptD('');
        fetchBankQuestions();
      })
      .catch(err => alert("Database Insertion Error: " + err.message));
  };

  const handleDeleteQuestion = (id) => {
    if (window.confirm("Are you sure you want to permanently delete this question from the repository?")) {
      axios.delete(`http://localhost:8082/api/question-bank/${id}`)
        .then(() => fetchBankQuestions())
        .catch(err => console.error(err));
    }
  };

  // Helper function to extract cleanly formatted data for the UI view layer
  const parseQuestionData = (rawText) => {
    if (String(rawText).startsWith('[ACTIVITY]')) {
      return { category: 'LESSON ACTIVITY', cleanText: String(rawText).replace('[ACTIVITY] ', '') };
    }
    return { category: 'ONLINE EXAM', cleanText: String(rawText).replace('[EXAM] ', '') };
  };

  // Filter the display matrix strictly based on selected UI controllers
  const filteredDisplayQuestions = bankQuestions.filter(q => {
    const isGradeMatch = String(q.grade).toLowerCase() === filterGrade.toLowerCase();
    const parsed = parseQuestionData(q.question_text);
    
    if (filterCategory === 'EXAM') {
      return isGradeMatch && parsed.category === 'ONLINE EXAM';
    }
    if (filterCategory === 'ACTIVITY') {
      return isGradeMatch && parsed.category === 'LESSON ACTIVITY';
    }
    return isGradeMatch;
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', fontFamily: 'sans-serif' }}>
      
      {/* Studio Banner Header */}
      <div style={styles.topHeaderDock}>
        <div>
          <h2 style={styles.mainTitle}>Centralized Question Bank Repository</h2>
          <p style={styles.subTitle}>Subject Stream: <span style={{ color: '#16a34a', fontWeight: 'bold' }}>{currentSubject}</span> | Managed By: <b>{userName || 'Teacher'}</b></p>
        </div>
      </div>

      {/* Two Column Workspace Control Layer */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.2fr', gap: '25px', alignItems: 'start' }}>
        
        {/* LEFT PANEL: QUESTION CREATION FORM WITH SEGMENTATION */}
        <div style={styles.card('#6b21a8')}>
          <h3 style={styles.formTitle}>Create Master Question</h3>
          
          <form onSubmit={handleAddQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
              <div>
                <label style={styles.fieldLabel}>Question Purpose</label>
                <select value={questionCategory} onChange={e => setQuestionCategory(e.target.value)} style={styles.premiumInput}>
                  <option value="EXAM">🎯 Online Exam Question</option>
                  <option value="ACTIVITY">🧩 Lesson Activity Question</option>
                </select>
              </div>
              <div>
                <label style={styles.fieldLabel}>Question Structure</label>
                <select value={questionType} onChange={e => setQuestionType(e.target.value)} style={styles.premiumInput}>
                  <option value="MCQ">Multiple Choice (MCQ)</option>
                  <option value="SHORT_ANSWER">Short Written Answer</option>
                </select>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
              <div>
                <label style={styles.fieldLabel}>Target Grade</label>
                <select value={targetGrade} onChange={e => setTargetGrade(e.target.value)} style={styles.premiumInput}>
                  <option value="Grade 6">Grade 6</option>
                  <option value="Grade 7">Grade 7</option>
                  <option value="Grade 8">Grade 8</option>
                  <option value="Grade 9">Grade 9</option>
                </select>
              </div>
              <div>
                <label style={styles.fieldLabel}>Subject Stream</label>
                <input type="text" value={currentSubject} disabled style={{ ...styles.premiumInput, backgroundColor: '#e2e8f0', fontWeight: 'bold' }} />
              </div>
            </div>

            <div>
              <label style={styles.fieldLabel}>Question Content</label>
              <textarea placeholder={questionType === 'SHORT_ANSWER' ? "Use ______ for fill in the blank spacing..." : "Type the core question text here..."} value={questionText} onChange={e => setQuestionText(e.target.value)} required style={styles.premiumTextArea} />
            </div>

            {/* Render choices dynamically for MCQs */}
            {questionType === 'MCQ' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', padding: '10px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #cbd5e1' }}>
                <label style={styles.fieldLabel}>Configure Answer Choices</label>
                <input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.premiumInput} />
                <input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.premiumInput} />
                <input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.premiumInput} />
                <input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.premiumInput} />
              </div>
            )}

            <div>
              <label style={styles.fieldLabel}>Correct Evaluation Key</label>
              <input type="text" placeholder={questionType === 'MCQ' ? "e.g., A / B / C / D" : "Type targeted correct answer key..."} value={correctAnswer} onChange={e => setCorrectAnswer(e.target.value)} required style={styles.premiumInput} />
            </div>

            <button type="submit" style={styles.submitBtn('#6b21a8')}>Commit to Question Bank 💾</button>
          </form>
        </div>

        {/* RIGHT PANEL: LIVE QUESTIONS BANK LIST WITH FILTER SWITCH */}
        <div style={styles.card('#145c2e')}>
          <h3 style={styles.formTitle}>Live Repository Inventory</h3>
          
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '15px' }}>
            <select value={filterGrade} onChange={e => setFilterGrade(e.target.value)} style={styles.premiumInput}>
              <option value="Grade 6">Grade 6</option>
              <option value="Grade 7">Grade 7</option>
              <option value="Grade 8">Grade 8</option>
              <option value="Grade 9">Grade 9</option>
            </select>
            <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} style={styles.premiumInput}>
              <option value="ALL">All Purposes</option>
              <option value="EXAM">🎯 Online Exams Only</option>
              <option value="ACTIVITY">🧩 Lesson Activities Only</option>
            </select>
          </div>

          <div style={styles.scrollContainer}>
            {filteredDisplayQuestions.map((q, index) => {
              const parsed = parseQuestionData(q.question_text);
              return (
                <div key={q.id || index} style={styles.itemRow}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontSize: '11px', fontWeight: 'bold', color: '#64748b' }}>Bank Key ID: #{q.id}</span>
                    <div style={{ display: 'flex', gap: '4px' }}>
                      <span style={styles.badgePurpose(parsed.category)}>{parsed.category}</span>
                      <span style={styles.badgeType(q.option_a ? 'MCQ' : 'SHORT')}>{q.option_a ? 'MCQ' : 'Short Field'}</span>
                    </div>
                  </div>

                  <p style={styles.qTextDisplay}><b>({index + 1})</b> {parsed.cleanText}</p>
                  
                  {q.option_a && (
                    <div style={styles.mcqGridOptions}>
                      <div>A) {q.option_a}</div><div>B) {q.option_b}</div>
                      <div>C) {q.option_c}</div><div>D) {q.option_d}</div>
                    </div>
                  )}

                  <div style={styles.itemFooter}>
                    <span style={{ color: '#16a34a', fontWeight: 'bold' }}>Evaluation Key: {q.correct_answer || q.correct_option}</span>
                    <button type="button" onClick={() => handleDeleteQuestion(q.id)} style={styles.deleteBtn}>Delete</button>
                  </div>
                </div>
              );
            })}
            {filteredDisplayQuestions.length === 0 && (
              <p style={styles.emptyText}>No matching master questions registered under this category scope.</p>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

const styles = {
  topHeaderDock: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f8fafc', padding: '15px 20px', borderRadius: '12px', border: '1px solid #cbd5e1' },
  mainTitle: { margin: 0, fontSize: '19px', fontWeight: 'bold', color: '#1e293b' },
  subTitle: { margin: '4px 0 0 0', fontSize: '13px', color: '#64748b' },
  card: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '16px', borderTop: `5px solid ${color}`, borderLeft: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  formTitle: { margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b', fontWeight: 'bold' },
  fieldLabel: { display: 'block', fontSize: '11px', fontWeight: 'bold', color: '#475569', marginBottom: '3px' },
  premiumInput: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13px', boxSizing: 'border-box', outline: 'none' },
  premiumTextArea: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13px', boxSizing: 'border-box', height: '55px', resize: 'none', outline: 'none' },
  submitBtn: (color) => ({ color: 'white', backgroundColor: color, border: 'none', padding: '12px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13px', cursor: 'pointer', marginTop: '5px', width: '100%' }),
  scrollContainer: { display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '440px', overflowY: 'auto' },
  itemRow: { backgroundColor: '#f8fafc', padding: '15px', borderRadius: '12px', border: '1px solid #e2e8f0' },
  qTextDisplay: { margin: '8px 0', fontSize: '13.5px', fontWeight: '600', color: '#334155' },
  mcqGridOptions: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4px', fontSize: '12px', color: '#64748b', marginBottom: '8px', paddingLeft: '5px' },
  itemFooter: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '10px', borderTop: '1px dashed #e2e8f0', paddingTop: '8px', fontSize: '12.5px' },
  deleteBtn: { padding: '5px 12px', border: 'none', backgroundColor: '#fee2e2', color: '#b91c1c', borderRadius: '6px', cursor: 'pointer', fontSize: '11px', fontWeight: 'bold' },
  badgePurpose: (cat) => ({ fontSize: '9px', fontWeight: 'bold', padding: '2px 6px', borderRadius: '4px', backgroundColor: cat === 'ONLINE EXAM' ? '#ffe2e2' : '#e0f2fe', color: cat === 'ONLINE EXAM' ? '#991b1b' : '#0369a1' }),
  badgeType: (type) => ({ fontSize: '9px', fontWeight: 'bold', padding: '2px 6px', borderRadius: '4px', backgroundColor: '#e2e8f0', color: '#334155' }),
  emptyText: { color: '#94a3b8', fontStyle: 'italic', fontSize: '12.5px', textAlign: 'center', padding: '30px' }
};
